BEGIN;
DO $$ BEGIN
 IF NOT EXISTS (SELECT 1 FROM public.courses WHERE id='cisp430' AND subject_id='computer_science') THEN RAISE EXCEPTION 'CISP 430 course missing or wrong subject'; END IF;
 IF (SELECT count(*) FROM public.assignments WHERE course_id='cisp430' AND id IN ('7c7ddad2-e6cb-41a9-975e-bcf9f509a8a0','dc6859c4-de0c-4247-82d4-b8abe6fbbceb'))<>2 THEN RAISE EXCEPTION 'Expected CISP 430 assignment IDs missing'; END IF;
END $$;
UPDATE public.courses SET description='C++ data structures coursework at American River College. Featured archive programs: sorted doubly linked names with forward/reverse traversal, and undirected nonnegative-weight Dijkstra shortest paths with predecessor reconstruction. Supporting pointer, recursion, merge-sort and tree exercises include unfinished drafts. Browser adaptations explain the tested featured programs; no completed library-management application is claimed.' WHERE id='cisp430';
UPDATE public.assignments SET title='Sorted Doubly Linked List Manager', description='C++ sorted doubly linked list: insertion, first-match deletion, forward/reverse file output and cleanup. Assignment1.cpp and DoubleLinkedList.cpp were compiled and tested on the supplied fixture. Browser trace follows DoubleLinkedList.cpp with bounded input and explicit node links.', assignment_type='C++ / Doubly linked list', demo_url='/course/cisp430/assignment/linked-list' WHERE id='7c7ddad2-e6cb-41a9-975e-bcf9f509a8a0' AND course_id='cisp430';
UPDATE public.assignments SET title='Dijkstra’s Shortest Path Algorithm Implementation', description='C++ undirected nonnegative-weight graph with adjacency lists, min-priority queue, distances and predecessor-based path reconstruction. Executed on the supplied six-vertex fixture. Browser adaptation adds an inspectable trace with a sorted queue and small graph limits.', assignment_type='C++ / Graph algorithm', demo_url='/course/cisp430/assignment/dijkstra' WHERE id='dc6859c4-de0c-4247-82d4-b8abe6fbbceb' AND course_id='cisp430';
COMMIT;
